package com.paytrace.ledger;
import jakarta.persistence.*; import java.math.BigDecimal; import java.util.UUID;
@Entity @Table(name="ledger_entries") public class LedgerEntryEntity { @Id private UUID id; @Column(name="transaction_id",nullable=false) private UUID transactionId; @Column(name="account_code",nullable=false) private String accountCode; @Enumerated(EnumType.STRING) @Column(nullable=false) private EntryDirection direction; @Column(nullable=false,precision=19,scale=2) private BigDecimal amount; @Column(nullable=false,length=3) private String currency; protected LedgerEntryEntity(){} public LedgerEntryEntity(UUID tx,String account,EntryDirection direction,BigDecimal amount,String currency){id=UUID.randomUUID();transactionId=tx;accountCode=account;this.direction=direction;this.amount=amount;this.currency=currency;} public UUID transactionId(){return transactionId;} public EntryDirection direction(){return direction;} public BigDecimal amount(){return amount;} public String accountCode(){return accountCode;} public String currency(){return currency;} }
